import test from 'node:test';import assert from 'node:assert/strict';
import {travelIntent,entranceFor,journeyFrame} from '../journey.js';
import {sceneLayout,validateLayout,modules,drawModule} from '../scenery.js';
import {applyEvent,initialState} from '../engine.js';
import {createRenderer} from '../renderer.js';
test('viagem espera o resultado sem timeout visual e só então atravessa a entrada',()=>{const j={started:0,readyAt:null};for(const now of [50,5000,30000,90000]){const f=journeyFrame(j,now);assert.equal(f.phase,'walking');assert.equal(f.entranceX,null);assert.equal(f.fade,0);}j.readyAt=90000;assert.equal(journeyFrame(j,90000).phase,'entering');assert.equal(journeyFrame(j,91800).phase,'arrived');assert.equal(entranceFor('village'),'gate');assert.equal(entranceFor('shop'),'door');assert.equal(entranceFor('dungeon'),'arch');assert.equal(entranceFor('forest'),'path');assert.equal(travelIntent('Vou para a loja').scene,'shop');assert.equal(travelIntent('Vou conversar com Borin'),null);assert.equal(travelIntent('Não vou para a vila'),null);});
test('composição modular persiste e rejeita módulos/posições fora do contrato',()=>{const s=initialState(),layout={ground:'wood',background:'wall',props:[{type:'door',x:900,y:400,layer:'mid',scale:1},{type:'table',x:200,y:500,color:'#78543a'}]};applyEvent(s,{type:'scene',scene:'shop',layout});assert.deepEqual(s.layout,layout);assert.equal(sceneLayout('shop',s.layout).props.length,2);const before=structuredClone(s);assert.throws(()=>applyEvent(s,{type:'scene',scene:'forest',layout:{ground:'lava'}}));assert.deepEqual(s,before);assert.throws(()=>validateLayout({props:[{type:'script',x:0,y:200}]}));assert.throws(()=>validateLayout({props:Array(25).fill(layout.props[0])}));});
test('destino só é aplicado após entrada; cancelamento preserva a origem',async()=>{let next;const old=globalThis.requestAnimationFrame;globalThis.requestAnimationFrame=fn=>{next=fn;};const c=new Proxy({measureText:s=>({width:s.length*9}),createRadialGradient:()=>({addColorStop(){}})}, {get:(o,k)=>k in o?o[k]:()=>{},set:(o,k,v)=>(o[k]=v,true)});const s=initialState(),r=createRenderer({getContext:()=>c},()=>s);try{r.beginTravel({scene:'shop'});next(performance.now()+30000);assert.equal(s.scene,'forest');assert.equal(r.getTravel().waiting,true);r.cancelTravel();assert.equal(r.getTravel(),null);let commits=0;const done=r.transition({scene:'shop'},()=>{commits++;applyEvent(s,{type:'scene',scene:'shop'});});assert.equal(commits,0);next(performance.now()+5000);assert.equal(s.scene,'shop');next(performance.now()+5500);await done;assert.equal(commits,1);assert.equal(r.getTravel(),null);for(const type of modules)drawModule(c,()=>{},{type,x:100,y:300},()=>{},0);}finally{r.stop();globalThis.requestAnimationFrame=old;}});
